"""Write a ready-to-run QLoRA launch script for a curriculum round.

Mirrors scripts/launch-qlora-round5-blueprints.py (the proven local flow):
GUITrainer from training/gui_trainer/engine, 4-bit, models out to
training/gui_trainer/models/, GGUF q4_k_m export automatic.

Deliberately does NOT run training — it prints the command so the user
starts it when they're ready (training occupies both GPUs for hours).
"""
from __future__ import annotations

from pathlib import Path

LAUNCH_TMPL = '''#!/usr/bin/env python3
"""Launch a curriculum fine-tune round (auto-generated by curriculum.py train).

Dataset: {dataset}
Rows: {rows}
"""
import os
import sys

BASE = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, BASE)

from training.gui_trainer.engine import GUITrainer  # noqa: E402

DATASET = r"{dataset}"
MODELS_DIR = os.path.join(BASE, "training", "gui_trainer", "models")


def main():
    if not os.path.exists(DATASET):
        print("[launch] ❌ dataset missing — run `python3 curriculum/curriculum.py dataset` first")
        sys.exit(1)
    with open(DATASET, encoding="utf-8") as f:
        n_rows = sum(1 for _ in f)
    print(f"[launch] curriculum round: {{n_rows}} rows from {{DATASET}}")
    trainer = GUITrainer(str(MODELS_DIR))
    trainer.update_config(
        model_name="Orion-zhen/Qwen2.5-7B-Instruct-Uncensored",
        quantization="4bit",
        dataset_path=DATASET,
        output_dir=os.path.join(MODELS_DIR, "curriculum-round"),
        # retention: keep prior capability when mixing with older rounds
        mix_paths=[os.path.join(BASE, "training", "dataset", "round8-code.jsonl")],
        mix_ratio=0.15,
    )
    trainer.train()


if __name__ == "__main__":
    main()
'''


def write_launch_script(out_dir: Path, dataset: Path) -> Path:
    rows = sum(1 for _ in open(dataset, encoding="utf-8")) if dataset.exists() else 0
    target = out_dir / "launch-curriculum-round.py"
    target.write_text(LAUNCH_TMPL.format(dataset=dataset, rows=rows), encoding="utf-8")
    return target


def print_instructions(out_dir: Path, dataset: Path, launch: Path) -> None:
    print("\n── Train (do NOT auto-run; occupies both GPUs for hours) ──")
    print("  1. (optional) stop the serving model so training has the GPUs:")
    print("     bash scripts/start-dspark.sh --stop")
    print(f"  2. python3 {launch}")
    print("     # or via torchrun if you want 2-GPU data-parallel:")
    print("     # torchrun --standalone --nproc_per_node=2 " + str(launch))
    print(f"  3. dataset: {dataset}")
    print("  4. GGUF export lands in training/gui_trainer/models/ automatically.")
    print("  5. Re-deploy the tuned model, then re-run `eval` to measure the delta.")
